import { existsSync } from "node:fs";
import { join } from "node:path";
import type { Metadata } from "next";
import ButtonLink from "@/components/Button";
import PageHeader from "@/components/PageHeader";
import SectionHeading from "@/components/SectionHeading";
import { DocumentIcon, DownloadIcon, MailIcon } from "@/components/icons";
import { site } from "@/lib/site";

export const metadata: Metadata = {
  title: "Paper Registration",
  description: `Download the printable solo or team registration form for the ${site.title}, in English and Punjabi.`,
};

/* The forms are generated by scripts/build-paper-forms.mts and committed. A
   form is listed only when its file is present, the same way the Rulebook
   lists its PDFs, so a missing file never becomes a dead link. */
const forms = [
  {
    file: "registration-form-solo.pdf",
    title: "Solo Rider Form",
    detail: "One rider · 1 page",
  },
  {
    file: "registration-form-team.pdf",
    title: "Team Form",
    detail: "Four riders, team leader first · 2 pages",
  },
];

const documentExists = (file: string) =>
  existsSync(join(process.cwd(), "public", "documents", file));

export default function PaperRegistrationPage() {
  const availableForms = forms
    .filter((form) => documentExists(form.file))
    .map((form) => ({ ...form, href: `/documents/${form.file}` }));

  return (
    <>
      <PageHeader
        title="Paper Registration"
        intro="Print a form, fill it in by hand, and hand it in. In English and Punjabi."
      />

      <section className="bg-cream">
        {/* Same left edge as the page heading above (PageHeader's max-w-6xl),
            with the text kept to a readable width, as on the Rulebook. */}
        <div className="mx-auto max-w-6xl space-y-16 px-6 py-16 [&>*]:max-w-4xl">
          <div>
            <SectionHeading>When to Use It</SectionHeading>
            <div className="mt-8 space-y-4 leading-7 text-brown/85">
              <p>
                Use the paper form if registering online is not practical for you: no email
                address, no phone or computer to fill in the online form, or you would rather
                write it out by hand. One form covers one solo rider or one team of four.
              </p>
              <p>
                Online is still the quickest way in. Your confirmation code arrives straight
                away, and you can check or correct your details yourself later.
              </p>
            </div>
          </div>

          <div>
            <SectionHeading>Download a Form</SectionHeading>
            {availableForms.length > 0 ? (
              <ul className="mt-8 grid gap-4 sm:grid-cols-2">
                {availableForms.map((form) => (
                  <li
                    key={form.file}
                    className="flex flex-col justify-between gap-5 rounded-2xl border border-bronze/25 bg-sand p-6"
                  >
                    <div className="flex items-start gap-4">
                      <DocumentIcon className="h-9 w-9 shrink-0 text-bronze" />
                      <div>
                        <h3 className="font-display text-2xl font-bold uppercase leading-none text-bronze-dark">
                          {form.title}
                        </h3>
                        <p className="mt-2 text-sm leading-5 text-brown/75">{form.detail}</p>
                        <p className="mt-1 text-sm leading-5 text-brown/75">
                          A4 · print it, or type into it on a computer
                        </p>
                      </div>
                    </div>
                    <div className="flex flex-wrap gap-3">
                      <a
                        href={form.href}
                        download
                        className="inline-flex items-center gap-2 rounded-lg bg-bronze px-5 py-2.5 font-display text-xs font-semibold uppercase tracking-[0.12em] text-cream transition-colors hover:bg-bronze-dark"
                      >
                        <DownloadIcon className="h-3.5 w-3.5" />
                        Download PDF
                      </a>
                      <a
                        href={form.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-2 rounded-lg border border-brown/30 px-4 py-2.5 font-display text-xs font-semibold uppercase tracking-[0.12em] text-brown transition-colors hover:border-bronze hover:text-bronze"
                      >
                        Open
                      </a>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="mt-8 leading-7 text-brown/85">
                {`The printable forms are being prepared. Email ${site.email} and we will send you one.`}
              </p>
            )}
          </div>

          <div>
            <SectionHeading>Hand It In</SectionHeading>
            <div className="mt-8 space-y-4 leading-7 text-brown/85">
              <p>
                Fill in every box and sign the declaration — on the team form, all four riders
                sign. Then email a clear photo or scan of every page to:
              </p>
              <a
                href={`mailto:${site.email}?subject=${encodeURIComponent("Paper registration form")}`}
                className="inline-flex items-center gap-3 break-all rounded-lg border border-bronze/30 bg-sand px-5 py-3 font-display text-lg font-semibold text-bronze-dark transition-colors hover:border-bronze hover:text-bronze"
              >
                <MailIcon className="h-5 w-5 shrink-0" />
                {site.email}
              </a>
              <p>or hand the paper form to the organisers.</p>
            </div>
          </div>

          <div>
            <SectionHeading>What Happens Next</SectionHeading>
            <div className="mt-8 space-y-4 leading-7 text-brown/85">
              <p>
                The organisers enter your form into the registration system for you. Every rider
                on it then receives a confirmation code — by email if an address was written on
                the form, otherwise from the organisers directly.
              </p>
              <p>
                {`Bring your code to check-in on ${site.checkInDate}, the day before the event. Only riders who check in are drawn into the brackets.`}
              </p>
            </div>
          </div>

          <div className="rounded-2xl border border-bronze/25 bg-sand p-6 sm:p-8">
            <p className="font-display text-xl font-bold uppercase tracking-wide text-bronze-dark">
              Rather register online?
            </p>
            <div className="mt-5 flex flex-wrap gap-4">
              <ButtonLink href="/register/solo">Register Solo</ButtonLink>
              <ButtonLink href="/register-team" variant="outline">
                Register a Team
              </ButtonLink>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
